import{_ as r,C as s,o,c as n,j as e,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const f=JSON.parse(`{"title":"Share a run live","description":"Let a teammate watch the tests of a Playwright run on your machine from its page on the team instance, as a CI run's live view: Share live from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app.","frontmatter":{"title":"Share a run live","description":"Let a teammate watch the tests of a Playwright run on your machine from its page on the team instance, as a CI run's live view: Share live from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/share-live.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/share-live.html"}],["meta",{"property":"og:title","content":"Share a run live | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Let a teammate watch the tests of a Playwright run on your machine from its page on the team instance, as a CI run's live view: Share live from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app."}]]},"headers":[],"relativePath":"features/share-live.md","filePath":"features/share-live.md","lastUpdated":1793944033000}`),l={name:"features/share-live.md"};function p(u,t,c,g,w,m){const a=s("Needs");return o(),n("div",null,[t[0]||(t[0]=e("h1",{id:"share-a-run-live",tabindex:"-1"},[i("Share a run live "),e("a",{class:"header-anchor",href:"#share-a-run-live","aria-label":'Permalink to "Share a run live"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),t[1]||(t[1]=d('<p>A run on your machine sends the team instance nothing of its pages until you share it. Shared, it gets the <a href="./live-view.html">live view</a> a CI run gets: a teammate opens its page and watches each worker, and its stops show on its rows. Sharing changes nothing for the run itself, and stops as you choose, or as the tool that shared it closes.</p><h2 id="share-and-stop" tabindex="-1">Share and stop <a class="header-anchor" href="#share-and-stop" aria-label="Permalink to &quot;Share and stop&quot;">​</a></h2><p>Choose <strong>Share live</strong> while a local run executes to let a teammate watch it. The run must report to a team instance whose project enables live view, and connect to an editor or the desktop app for controls.</p><table tabindex="0"><thead><tr><th>Where</th><th>Share</th><th>Stop</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Share the run live on the team instance</strong>, or the status bar&#39;s broadcast icon</td><td><strong>Piwi: Stop sharing the run live</strong>, or the status bar&#39;s <strong>Live</strong></td></tr><tr><td>JetBrains IDEs</td><td><strong>Tools → Piwi → Share the Run Live</strong></td><td><strong>Tools → Piwi → Stop Sharing the Run Live</strong></td></tr><tr><td>Piwi Picker&#39;s <a href="./runs-window.html">Runs window</a></td><td><strong>Share live</strong> under the run&#39;s name</td><td><strong>Stop sharing</strong></td></tr><tr><td>The desktop app&#39;s <a href="./desktop-runs.html">Local runs tray</a></td><td><strong>Share live</strong> above the run&#39;s workers</td><td><strong>Stop sharing</strong></td></tr></tbody></table><p>The first share in a window asks for confirmation. The shared run shows its destination, viewer count and a link to copy.</p><p>Until then, its workers send nothing, and its running tests say <strong>Not shared live</strong> where <strong>Watch</strong> would be. Once shared, its stops (the call, its file and line, the test&#39;s title) reach everyone with the run&#39;s page open, and images only those watching. <strong>Stop sharing</strong> closes the views within seconds and clears <strong>Paused</strong> from the rows. Closing the editor or the desktop app stops it too.</p><p>A run that cannot be shared says why: it reports to no instance or to the desktop app, it does not stream its results, its project has the live view off, the reporter&#39;s global setup did not register it, or the instance did not register the run as it started. A sharing that stops on its own says why (the live view turned off, or the instance stopped answering), and <strong>Share live</strong> shows again: shared again, the run streams once the instance answers with its live view on, a restarted instance taking the run&#39;s key back. A run the instance no longer holds live cannot be shared again.</p><h2 id="from-the-desktop-app" tabindex="-1">From the desktop app <a class="header-anchor" href="#from-the-desktop-app" aria-label="Permalink to &quot;From the desktop app&quot;">​</a></h2><p>A run that reports to the <a href="./desktop-runs.html">desktop app</a> itself (a reproduction, a bisect, a <strong>Re-run</strong> in a folder that names no instance, a run your editor started) cannot be shared: the app hands out no live view key, since no teammate reaches it. Its tray offers no <strong>Share live</strong> for it, the app&#39;s project settings have no <strong>Live view</strong> section, and on the run&#39;s page its running tests offer <a href="./desktop-runs.html#watch-live"><strong>Watch</strong> and <strong>Pause and watch</strong></a>, shown in the app&#39;s tray from the app itself. A run your editor started says <strong>See its page at a stop</strong> there: its page shows where the editor steers it.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./live-view.html">Live view of a run</a>: what a teammate sees, what is sent and what is kept</li><li><a href="./editor-run-control.html">Editor run control</a>: the controls of a run your editor starts</li><li><a href="./runs-window.html">Runs window</a>: Piwi Picker&#39;s view of your runs</li><li><a href="./desktop-runs.html">Desktop app runs</a>: the desktop app&#39;s runs and its tray</li></ul>',11))])}const k=r(l,[["render",p]]);export{f as __pageData,k as default};
